PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE IF NOT EXISTS "d1_migrations"(
		id         INTEGER PRIMARY KEY AUTOINCREMENT,
		name       TEXT UNIQUE,
		applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL
);
CREATE TABLE `sessions` (
	`id` text PRIMARY KEY NOT NULL,
	`user_id` text NOT NULL,
	`expires_at` integer NOT NULL,
	`user_agent` text,
	`ip_address` text,
	`created_at` integer NOT NULL,
	FOREIGN KEY (`user_id`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE cascade
);
CREATE TABLE `users` (
	`id` text PRIMARY KEY NOT NULL,
	`email` text NOT NULL,
	`password_hash` text NOT NULL,
	`status` text DEFAULT 'ACTIVE' NOT NULL,
	`created_at` integer NOT NULL,
	`updated_at` integer NOT NULL,
	`last_login_at` integer,
	`mfa_enabled` integer DEFAULT false NOT NULL,
	`mfa_secret` text,
	`role` text DEFAULT 'USER' NOT NULL
, `display_name` text, `first_name` text, `last_name` text, `email_verified` integer DEFAULT false, `avatar_url` text, `is_merchant` integer DEFAULT false NOT NULL, `p2p_total_orders` integer DEFAULT 0 NOT NULL, `p2p_completion_rate` text DEFAULT '0' NOT NULL, `p2p_positive_feedback` integer DEFAULT 0 NOT NULL, `p2p_negative_feedback` integer DEFAULT 0 NOT NULL, `display_id` text, `verification_token` text, `verification_expires_at` integer);
CREATE TABLE `wallets` (
	`id` text PRIMARY KEY NOT NULL,
	`user_id` text NOT NULL,
	`asset_symbol` text NOT NULL,
	`balance` text DEFAULT '0' NOT NULL,
	`locked_balance` text DEFAULT '0' NOT NULL,
	`created_at` integer NOT NULL,
	`updated_at` integer NOT NULL, `type` text DEFAULT 'REAL' NOT NULL, `escrow_balance` text DEFAULT '0' NOT NULL, `display_id` text,
	FOREIGN KEY (`user_id`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE cascade
);
CREATE TABLE `kyc_profiles` (
	`id` text PRIMARY KEY NOT NULL,
	`user_id` text NOT NULL,
	`first_name` text NOT NULL,
	`last_name` text NOT NULL,
	`date_of_birth` text NOT NULL,
	`country` text NOT NULL,
	`document_type` text NOT NULL,
	`document_number` text NOT NULL,
	`document_front_url` text NOT NULL,
	`document_back_url` text,
	`selfie_url` text NOT NULL,
	`status` text DEFAULT 'PENDING' NOT NULL,
	`reviewed_by` text,
	`rejection_reason` text,
	`created_at` integer NOT NULL,
	`updated_at` integer NOT NULL, `display_id` text,
	FOREIGN KEY (`user_id`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`reviewed_by`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE no action
);
CREATE TABLE `ledger_accounts` (
	`id` text PRIMARY KEY NOT NULL,
	`user_id` text,
	`type` text NOT NULL,
	`asset_symbol` text NOT NULL,
	`created_at` integer NOT NULL, `environment` text DEFAULT 'REAL' NOT NULL,
	FOREIGN KEY (`user_id`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE no action
);
CREATE TABLE `ledger_entries` (
	`id` text PRIMARY KEY NOT NULL,
	`transaction_id` text NOT NULL,
	`account_id` text NOT NULL,
	`direction` text NOT NULL,
	`amount` text NOT NULL,
	`asset_symbol` text NOT NULL,
	`created_at` integer NOT NULL, `environment` text DEFAULT 'REAL' NOT NULL,
	FOREIGN KEY (`transaction_id`) REFERENCES `ledger_transactions`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`account_id`) REFERENCES `ledger_accounts`(`id`) ON UPDATE no action ON DELETE no action
);
CREATE TABLE `ledger_transactions` (
	`id` text PRIMARY KEY NOT NULL,
	`idempotency_key` text NOT NULL,
	`reference_type` text NOT NULL,
	`reference_id` text NOT NULL,
	`status` text NOT NULL,
	`created_at` integer NOT NULL
, `environment` text DEFAULT 'REAL' NOT NULL, `display_id` text);
CREATE TABLE `markets` (
	`id` text PRIMARY KEY NOT NULL,
	`symbol` text NOT NULL,
	`base_asset` text NOT NULL,
	`quote_asset` text NOT NULL,
	`status` text DEFAULT 'ACTIVE' NOT NULL,
	`min_price` text NOT NULL,
	`max_price` text NOT NULL,
	`tick_size` text NOT NULL,
	`min_amount` text NOT NULL,
	`step_size` text NOT NULL,
	`maker_fee` text DEFAULT '0.001' NOT NULL,
	`taker_fee` text DEFAULT '0.001' NOT NULL,
	`created_at` integer NOT NULL
, `type` text DEFAULT 'SPOT' NOT NULL, `max_leverage` text DEFAULT '100' NOT NULL);
CREATE TABLE `orders` (
	`id` text PRIMARY KEY NOT NULL,
	`user_id` text NOT NULL,
	`market_symbol` text NOT NULL,
	`side` text NOT NULL,
	`type` text NOT NULL,
	`status` text DEFAULT 'OPEN' NOT NULL,
	`price` text,
	`amount` text NOT NULL,
	`filled_amount` text DEFAULT '0' NOT NULL,
	`remaining_amount` text NOT NULL,
	`created_at` integer NOT NULL,
	`updated_at` integer NOT NULL, `mode` text DEFAULT 'REAL' NOT NULL, `display_id` text,
	FOREIGN KEY (`user_id`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE no action,
	FOREIGN KEY (`market_symbol`) REFERENCES `markets`(`symbol`) ON UPDATE no action ON DELETE no action
);
CREATE TABLE `p2p_ads` (
	`id` text PRIMARY KEY NOT NULL,
	`user_id` text NOT NULL,
	`type` text NOT NULL,
	`asset` text NOT NULL,
	`fiat` text NOT NULL,
	`price` text NOT NULL,
	`total_amount` text NOT NULL,
	`available_amount` text NOT NULL,
	`min_limit` text NOT NULL,
	`max_limit` text NOT NULL,
	`payment_methods` text NOT NULL,
	`terms` text,
	`status` text DEFAULT 'ACTIVE' NOT NULL,
	`created_at` integer NOT NULL,
	`updated_at` integer NOT NULL, `mode` text DEFAULT 'REAL' NOT NULL, `is_floating` integer DEFAULT false NOT NULL, `price_margin` text, `payment_window` integer DEFAULT 15 NOT NULL, `auto_reply` text, `country_restrictions` text, `display_id` text,
	FOREIGN KEY (`user_id`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE no action
);
CREATE TABLE `p2p_messages` (
	`id` text PRIMARY KEY NOT NULL,
	`order_id` text NOT NULL,
	`sender_id` text NOT NULL,
	`content` text NOT NULL,
	`attachment_url` text,
	`created_at` integer NOT NULL, `mode` text DEFAULT 'REAL' NOT NULL, `type` text DEFAULT 'TEXT' NOT NULL, `is_read` integer DEFAULT false NOT NULL,
	FOREIGN KEY (`order_id`) REFERENCES `p2p_orders`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`sender_id`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE no action
);
CREATE TABLE `wallet_transactions` (
	`id` text PRIMARY KEY NOT NULL,
	`user_id` text NOT NULL,
	`type` text NOT NULL,
	`asset_symbol` text NOT NULL,
	`amount` text NOT NULL,
	`fee` text DEFAULT '0' NOT NULL,
	`status` text NOT NULL,
	`destination` text,
	`network` text,
	`reference` text,
	`created_at` integer NOT NULL,
	`updated_at` integer NOT NULL, `mode` text DEFAULT 'REAL' NOT NULL, `display_id` text, `original_currency` text, `original_amount` text, `conversion_rate` text, `gross_amount` text, `total_fees` text, `net_amount` text,
	FOREIGN KEY (`user_id`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE cascade
);
CREATE TABLE `notifications` (
	`id` text PRIMARY KEY NOT NULL,
	`user_id` text NOT NULL,
	`title` text NOT NULL,
	`message` text NOT NULL,
	`type` text DEFAULT 'SYSTEM' NOT NULL,
	`is_read` integer DEFAULT false NOT NULL,
	`created_at` integer NOT NULL,
	FOREIGN KEY (`user_id`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE cascade
);
CREATE TABLE `ticket_messages` (
	`id` text PRIMARY KEY NOT NULL,
	`ticket_id` text NOT NULL,
	`sender_id` text NOT NULL,
	`is_admin` integer DEFAULT false NOT NULL,
	`content` text NOT NULL,
	`created_at` integer NOT NULL, `is_internal_note` integer DEFAULT false NOT NULL, `attachment_base64` text,
	FOREIGN KEY (`ticket_id`) REFERENCES `tickets`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`sender_id`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE no action
);
CREATE TABLE `tickets` (
	`id` text PRIMARY KEY NOT NULL,
	`user_id` text NOT NULL,
	`subject` text NOT NULL,
	`category` text NOT NULL,
	`status` text DEFAULT 'OPEN' NOT NULL,
	`priority` text DEFAULT 'MEDIUM' NOT NULL,
	`created_at` integer NOT NULL,
	`updated_at` integer NOT NULL, `display_id` text,
	FOREIGN KEY (`user_id`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE cascade
);
CREATE TABLE `bank_transfers` (
	`id` text PRIMARY KEY NOT NULL,
	`user_id` text NOT NULL,
	`amount` text NOT NULL,
	`currency` text NOT NULL,
	`bank_reference` text,
	`proof_document_url` text,
	`status` text DEFAULT 'PENDING' NOT NULL,
	`rejection_reason` text,
	`reviewed_by` text,
	`reviewed_at` integer,
	`created_at` integer NOT NULL,
	`updated_at` integer NOT NULL, `display_id` text,
	FOREIGN KEY (`user_id`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE no action
);
CREATE TABLE `cregis_deposits` (
	`id` text PRIMARY KEY NOT NULL,
	`user_id` text NOT NULL,
	`cid` text,
	`txid` text,
	`asset_symbol` text NOT NULL,
	`amount` text NOT NULL,
	`from_address` text,
	`to_address` text,
	`status` text DEFAULT 'PENDING' NOT NULL,
	`created_at` integer NOT NULL,
	`updated_at` integer NOT NULL, `display_id` text,
	FOREIGN KEY (`user_id`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE no action
);
CREATE TABLE `cregis_payouts` (
	`id` text PRIMARY KEY NOT NULL,
	`user_id` text NOT NULL,
	`third_party_id` text NOT NULL,
	`txid` text,
	`asset_symbol` text NOT NULL,
	`amount` text NOT NULL,
	`fee` text DEFAULT '0' NOT NULL,
	`to_address` text NOT NULL,
	`status` text DEFAULT 'PENDING' NOT NULL,
	`created_at` integer NOT NULL,
	`updated_at` integer NOT NULL, `display_id` text,
	FOREIGN KEY (`user_id`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE no action
);
CREATE TABLE `bank_accounts` (
	`id` text PRIMARY KEY NOT NULL,
	`environment` text DEFAULT 'REAL' NOT NULL,
	`bank_name` text NOT NULL,
	`account_holder` text NOT NULL,
	`account_number` text NOT NULL,
	`ifsc` text,
	`swift` text,
	`branch` text,
	`currency` text NOT NULL,
	`country` text,
	`instructions` text,
	`active` integer DEFAULT true NOT NULL,
	`default_account` integer DEFAULT false NOT NULL,
	`created_at` integer NOT NULL,
	`updated_at` integer NOT NULL
);
CREATE TABLE `real_manual_deposits` (
	`id` text PRIMARY KEY NOT NULL,
	`deposit_id` text NOT NULL,
	`user_id` text NOT NULL,
	`amount` real NOT NULL,
	`asset` text NOT NULL,
	`payment_reference` text NOT NULL,
	`transaction_hash` text,
	`proof_file_url` text,
	`remarks` text,
	`status` text DEFAULT 'PENDING' NOT NULL,
	`reviewed_by` text,
	`reviewed_at` integer,
	`rejection_reason` text,
	`created_at` integer NOT NULL,
	`updated_at` integer NOT NULL, `display_id` text, `original_currency` text, `original_amount` text, `conversion_rate` text, `gross_usdt` text, `deposit_fee` text, `other_fees` text, `total_fees` text, `net_usdt` text, `expected_wallet_credit` text, `method` text DEFAULT 'MANUAL',
	FOREIGN KEY (`user_id`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE no action
);
CREATE TABLE `payment_methods` (
	`id` text PRIMARY KEY NOT NULL,
	`environment` text DEFAULT 'REAL' NOT NULL,
	`method` text NOT NULL,
	`enabled` integer DEFAULT true NOT NULL,
	`maintenance_mode` integer DEFAULT false NOT NULL,
	`display_order` integer NOT NULL,
	`min_amount` real NOT NULL,
	`max_amount` real,
	`fee_type` text DEFAULT 'ZERO' NOT NULL,
	`fee_value` real DEFAULT 0 NOT NULL,
	`supported_assets` text,
	`supported_networks` text,
	`instructions` text,
	`created_at` integer NOT NULL,
	`updated_at` integer NOT NULL,
	`updated_by` text
);
CREATE TABLE `binary_options` (
	`id` text PRIMARY KEY NOT NULL,
	`user_id` text NOT NULL,
	`market_symbol` text NOT NULL,
	`mode` text DEFAULT 'REAL' NOT NULL,
	`direction` text NOT NULL,
	`amount` text NOT NULL,
	`entry_price` text NOT NULL,
	`settle_price` text,
	`status` text DEFAULT 'PENDING' NOT NULL,
	`payout_multiplier` text DEFAULT '1.8' NOT NULL,
	`expires_at` integer NOT NULL,
	`created_at` integer NOT NULL,
	`updated_at` integer NOT NULL, `display_id` text,
	FOREIGN KEY (`user_id`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE no action,
	FOREIGN KEY (`market_symbol`) REFERENCES `markets`(`symbol`) ON UPDATE no action ON DELETE no action
);
CREATE TABLE `positions` (
	`id` text PRIMARY KEY NOT NULL,
	`user_id` text NOT NULL,
	`market_symbol` text NOT NULL,
	`mode` text DEFAULT 'REAL' NOT NULL,
	`side` text NOT NULL,
	`status` text DEFAULT 'OPEN' NOT NULL,
	`leverage` text DEFAULT '1' NOT NULL,
	`margin_type` text DEFAULT 'ISOLATED' NOT NULL,
	`margin_amount` text NOT NULL,
	`entry_price` text NOT NULL,
	`liquidation_price` text NOT NULL,
	`amount` text NOT NULL,
	`realized_pnl` text DEFAULT '0' NOT NULL,
	`created_at` integer NOT NULL,
	`updated_at` integer NOT NULL, `display_id` text,
	FOREIGN KEY (`user_id`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE no action,
	FOREIGN KEY (`market_symbol`) REFERENCES `markets`(`symbol`) ON UPDATE no action ON DELETE no action
);
CREATE TABLE IF NOT EXISTS "trades" (
	`id` text PRIMARY KEY NOT NULL,
	`market_symbol` text NOT NULL,
	`mode` text DEFAULT 'REAL' NOT NULL,
	`maker_order_id` text NOT NULL,
	`taker_order_id` text NOT NULL,
	`price` text NOT NULL,
	`amount` text NOT NULL,
	`maker_fee` text NOT NULL,
	`taker_fee` text NOT NULL,
	`created_at` integer NOT NULL, `display_id` text,
	FOREIGN KEY (`market_symbol`) REFERENCES `markets`(`symbol`) ON UPDATE no action ON DELETE no action
);
CREATE TABLE `p2p_disputes` (
	`id` text PRIMARY KEY NOT NULL,
	`order_id` text NOT NULL,
	`opener_id` text NOT NULL,
	`assigned_admin_id` text,
	`reason` text NOT NULL,
	`evidence_urls` text,
	`status` text DEFAULT 'OPEN' NOT NULL,
	`admin_notes` text,
	`created_at` integer NOT NULL,
	`updated_at` integer NOT NULL, `display_id` text,
	FOREIGN KEY (`order_id`) REFERENCES `p2p_orders`(`id`) ON UPDATE no action ON DELETE no action,
	FOREIGN KEY (`opener_id`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE no action,
	FOREIGN KEY (`assigned_admin_id`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE no action
);
CREATE TABLE `p2p_feedback` (
	`id` text PRIMARY KEY NOT NULL,
	`order_id` text NOT NULL,
	`from_user_id` text NOT NULL,
	`to_user_id` text NOT NULL,
	`type` text NOT NULL,
	`comment` text,
	`created_at` integer NOT NULL,
	FOREIGN KEY (`order_id`) REFERENCES `p2p_orders`(`id`) ON UPDATE no action ON DELETE no action,
	FOREIGN KEY (`from_user_id`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE no action,
	FOREIGN KEY (`to_user_id`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE no action
);
CREATE TABLE `p2p_payment_methods` (
	`id` text PRIMARY KEY NOT NULL,
	`user_id` text NOT NULL,
	`type` text NOT NULL,
	`name` text NOT NULL,
	`details` text NOT NULL,
	`is_active` integer DEFAULT true NOT NULL,
	`created_at` integer NOT NULL,
	`updated_at` integer NOT NULL,
	FOREIGN KEY (`user_id`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE cascade
);
CREATE TABLE IF NOT EXISTS "p2p_orders" (
	`id` text PRIMARY KEY NOT NULL,
	`ad_id` text NOT NULL,
	`buyer_id` text NOT NULL,
	`seller_id` text NOT NULL,
	`mode` text DEFAULT 'REAL' NOT NULL,
	`crypto_amount` text NOT NULL,
	`fiat_amount` text NOT NULL,
	`price` text NOT NULL,
	`status` text DEFAULT 'CREATED' NOT NULL,
	`payment_method` text NOT NULL,
	`payment_details` text,
	`expires_at` integer NOT NULL,
	`created_at` integer NOT NULL,
	`updated_at` integer NOT NULL, `display_id` text,
	FOREIGN KEY (`ad_id`) REFERENCES `p2p_ads`(`id`) ON UPDATE no action ON DELETE no action,
	FOREIGN KEY (`buyer_id`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE no action,
	FOREIGN KEY (`seller_id`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE no action
);
CREATE TABLE `expert_bookings` (
	`id` text PRIMARY KEY NOT NULL,
	`user_id` text NOT NULL,
	`expert_id` text NOT NULL,
	`service_id` text NOT NULL,
	`scheduled_at` integer,
	`status` text DEFAULT 'PENDING_PAYMENT' NOT NULL,
	`price` text NOT NULL,
	`currency` text NOT NULL,
	`platform_fee` text DEFAULT '0' NOT NULL,
	`expert_earnings` text DEFAULT '0' NOT NULL,
	`transaction_id` text,
	`expires_at` integer,
	`chat_enabled` integer DEFAULT true NOT NULL,
	`created_at` integer NOT NULL,
	`updated_at` integer NOT NULL, `display_id` text,
	FOREIGN KEY (`user_id`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE no action,
	FOREIGN KEY (`expert_id`) REFERENCES `expert_profiles`(`id`) ON UPDATE no action ON DELETE no action,
	FOREIGN KEY (`service_id`) REFERENCES `expert_services`(`id`) ON UPDATE no action ON DELETE no action
);
CREATE TABLE `expert_messages` (
	`id` text PRIMARY KEY NOT NULL,
	`booking_id` text NOT NULL,
	`sender_id` text NOT NULL,
	`content` text NOT NULL,
	`is_read` integer DEFAULT false NOT NULL,
	`created_at` integer NOT NULL,
	FOREIGN KEY (`booking_id`) REFERENCES `expert_bookings`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`sender_id`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE cascade
);
CREATE TABLE `expert_profiles` (
	`id` text PRIMARY KEY NOT NULL,
	`user_id` text NOT NULL,
	`bio` text,
	`experience_years` integer DEFAULT 0 NOT NULL,
	`languages` text,
	`categories` text,
	`rating` real DEFAULT 0 NOT NULL,
	`completed_services` integer DEFAULT 0 NOT NULL,
	`customers_helped` integer DEFAULT 0 NOT NULL,
	`verification_status` text DEFAULT 'PENDING' NOT NULL,
	`availability_status` text DEFAULT 'OFFLINE' NOT NULL,
	`created_at` integer NOT NULL,
	`updated_at` integer NOT NULL, `display_id` text,
	FOREIGN KEY (`user_id`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE cascade
);
CREATE TABLE `expert_reviews` (
	`id` text PRIMARY KEY NOT NULL,
	`booking_id` text NOT NULL,
	`user_id` text NOT NULL,
	`expert_id` text NOT NULL,
	`rating` real NOT NULL,
	`comment` text,
	`created_at` integer NOT NULL,
	FOREIGN KEY (`booking_id`) REFERENCES `expert_bookings`(`id`) ON UPDATE no action ON DELETE no action,
	FOREIGN KEY (`user_id`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE no action,
	FOREIGN KEY (`expert_id`) REFERENCES `expert_profiles`(`id`) ON UPDATE no action ON DELETE no action
);
CREATE TABLE `expert_services` (
	`id` text PRIMARY KEY NOT NULL,
	`expert_id` text NOT NULL,
	`title` text NOT NULL,
	`description` text NOT NULL,
	`category` text NOT NULL,
	`duration_minutes` integer NOT NULL,
	`price` text NOT NULL,
	`currency` text DEFAULT 'USD' NOT NULL,
	`pricing_type` text DEFAULT 'FIXED' NOT NULL,
	`status` text DEFAULT 'DRAFT' NOT NULL,
	`created_at` integer NOT NULL,
	`updated_at` integer NOT NULL,
	FOREIGN KEY (`expert_id`) REFERENCES `expert_profiles`(`id`) ON UPDATE no action ON DELETE cascade
);
CREATE TABLE `platform_settings` (
	`id` text PRIMARY KEY NOT NULL,
	`key` text NOT NULL,
	`value` text NOT NULL,
	`description` text,
	`updated_at` integer NOT NULL,
	`updated_by` text
);
CREATE TABLE `currency_rate_history` (
	`id` text PRIMARY KEY NOT NULL,
	`currency_code` text NOT NULL,
	`previous_rate` text,
	`new_rate` text NOT NULL,
	`changed_by` text NOT NULL,
	`changed_at` integer NOT NULL,
	FOREIGN KEY (`currency_code`) REFERENCES `currency_rates`(`code`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`changed_by`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE no action
);
CREATE TABLE `currency_rates` (
	`id` text PRIMARY KEY NOT NULL,
	`code` text NOT NULL,
	`name` text NOT NULL,
	`symbol` text NOT NULL,
	`rate_per_usdt` text NOT NULL,
	`decimal_precision` integer DEFAULT 2 NOT NULL,
	`status` text DEFAULT 'ACTIVE' NOT NULL,
	`last_updated` integer NOT NULL,
	`updated_by` text NOT NULL, `is_asset` integer DEFAULT false NOT NULL, `is_bank` integer DEFAULT true NOT NULL,
	FOREIGN KEY (`updated_by`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE no action
);
CREATE TABLE `asset_conversions` (
	`id` text PRIMARY KEY NOT NULL,
	`user_id` text NOT NULL,
	`original_asset` text NOT NULL,
	`original_amount` text NOT NULL,
	`conversion_rate` text NOT NULL,
	`gross_usdt` text NOT NULL,
	`deposit_fee` text DEFAULT '0' NOT NULL,
	`net_usdt` text NOT NULL,
	`status` text DEFAULT 'COMPLETED' NOT NULL,
	`reference_id` text NOT NULL,
	`created_at` integer NOT NULL,
	`updated_at` integer NOT NULL,
	FOREIGN KEY (`user_id`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE cascade
);
CREATE TABLE `global_sequences` (
	`entity_type` text PRIMARY KEY NOT NULL,
	`current_value` integer DEFAULT 0 NOT NULL
);
CREATE TABLE `email_delivery_logs` (
	`id` text PRIMARY KEY NOT NULL,
	`recipient` text NOT NULL,
	`subject` text NOT NULL,
	`event_type` text NOT NULL,
	`status` text DEFAULT 'PENDING' NOT NULL,
	`error_message` text,
	`created_at` integer NOT NULL
);
CREATE TABLE `api_keys` (
	`id` text PRIMARY KEY NOT NULL,
	`user_id` text NOT NULL,
	`name` text NOT NULL,
	`key_hash` text NOT NULL,
	`permissions` text NOT NULL,
	`last_used_at` integer,
	`status` text DEFAULT 'ACTIVE' NOT NULL,
	`created_at` integer NOT NULL,
	`updated_at` integer NOT NULL,
	FOREIGN KEY (`user_id`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE cascade
);
CREATE TABLE `audit_logs` (
	`id` text PRIMARY KEY NOT NULL,
	`admin_id` text NOT NULL,
	`action` text NOT NULL,
	`target` text NOT NULL,
	`ip_address` text,
	`details` text,
	`created_at` integer NOT NULL,
	FOREIGN KEY (`admin_id`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE cascade
);
CREATE TABLE `risk_alerts` (
	`id` text PRIMARY KEY NOT NULL,
	`type` text NOT NULL,
	`severity` text NOT NULL,
	`user_id` text,
	`details` text NOT NULL,
	`resolved` integer DEFAULT false NOT NULL,
	`resolved_by` text,
	`created_at` integer NOT NULL,
	`updated_at` integer NOT NULL,
	FOREIGN KEY (`user_id`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`resolved_by`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE no action
);
CREATE TABLE `smart_contracts` (
	`id` text PRIMARY KEY NOT NULL,
	`name` text NOT NULL,
	`chain` text NOT NULL,
	`address` text NOT NULL,
	`type` text NOT NULL,
	`status` text DEFAULT 'ACTIVE' NOT NULL,
	`balance_usd` integer,
	`last_checked_at` integer,
	`created_at` integer NOT NULL,
	`updated_at` integer NOT NULL
);
CREATE TABLE `system_backups` (
	`id` text PRIMARY KEY NOT NULL,
	`filename` text NOT NULL,
	`type` text DEFAULT 'FULL' NOT NULL,
	`size_bytes` integer NOT NULL,
